import React from 'react';
import { useFormContext } from 'react-hook-form';
import { PROBABILITY_VALUES, SEVERITY_VALUES, TOLERABILITY_ACTIONS, TOLERABILITY_COLORS } from '../constants/icaoMatrix';
import { LIKELIHOOD_VALUES, IMPACT_VALUES, RISK_LEVELS, calculateRiskLevel } from '../constants/integratedMatrix';
import { calculateICAORiskTolerability } from '../utils/riskCalculations';
import { useRiskMatrixStore } from '../stores/riskMatrixStore';
import clsx from 'clsx';

function RiskLevelDisplay({ likelihood, impact, probability, severity }) {
  const { matrixType } = useRiskMatrixStore();
  let riskLevel;
  let backgroundColor;
  let textColor;


    if (matrixType === 'ICAO' && probability && severity) {
        riskLevel = calculateICAORiskTolerability(probability, severity);
        backgroundColor = TOLERABILITY_COLORS[riskLevel]?.split(' ')[0] || 'bg-gray-100';
         textColor = TOLERABILITY_COLORS[riskLevel]?.split(' ')[1] || 'text-gray-800';
    }
     if (matrixType === 'Integrated' && likelihood && impact ) {
        riskLevel = calculateRiskLevel(likelihood, impact);
         backgroundColor =  RISK_LEVELS[riskLevel]?.color || 'bg-gray-100';
         textColor =  RISK_LEVELS[riskLevel]?.color || 'text-gray-800';
    }


  if(!riskLevel){
    return <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-gray-100"></span>
  }

  return (
    <span
      className={clsx(
        'inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium',
        backgroundColor,
        textColor
      )}
    >
      {riskLevel}
    </span>
  );
}

export default function AssessmentForm({ groupedAssessments, onSubmit, setValue, isSubmitting }) {
  const { matrixType } = useRiskMatrixStore();
     const { register } = useFormContext();

  return (
    <form onSubmit={onSubmit} className="space-y-6">
      {Object.entries(groupedAssessments).map(([eventId, { event, assessments }]) => (
        <div key={eventId} className="bg-white rounded-lg shadow-md p-6">
          <h3 className="text-xl font-semibold text-gray-800 mb-4">{event}</h3>
          <div className="overflow-x-auto">
            <table className="min-w-full border border-gray-200 divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Hazard
                  </th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Consequence
                  </th>
                  <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Current Controls
                  </th>
                  {matrixType === 'ICAO' && (
                    <>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Probability
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Severity
                      </th>
                    </>
                  )}
                  {matrixType === 'Integrated' && (
                    <>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Likelihood
                      </th>
                       <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                         Impact
                       </th>
                    </>
                    )}
                     <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                     Risk Level
                    </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {assessments.map((assessment, index) => (
                  <tr key={assessment.consequence_id}>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                      {assessment.hazard}
                    </td>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                      {assessment.consequence}
                    </td>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                      {assessment.current_controls}
                    </td>
                     {matrixType === 'ICAO' && (
                    <>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                      <select
                        {...register(`assessments.${index}.probability`)}
                        className="mt-1 block w-full rounded-md border-gray-300 focus:border-primary-main focus:ring focus:ring-primary-main focus:ring-opacity-50 text-sm"
                      >
                        <option value="">Select</option>
                        {Object.entries(PROBABILITY_VALUES).map(([key, value]) => (
                          <option key={key} value={value.value}>
                            {value.label}
                          </option>
                        ))}
                      </select>
                    </td>
                      <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                       <select
                          {...register(`assessments.${index}.severity`)}
                          className="mt-1 block w-full rounded-md border-gray-300 focus:border-primary-main focus:ring focus:ring-primary-main focus:ring-opacity-50 text-sm"
                       >
                          <option value="">Select</option>
                          {Object.entries(SEVERITY_VALUES).map(([key, value]) => (
                            <option key={key} value={value.value}>
                              {value.label}
                           </option>
                        ))}
                        </select>
                      </td>
                      </>
                      )}
                       {matrixType === 'Integrated' && (
                       <>
                    <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                        <select
                        {...register(`assessments.${index}.likelihood`)}
                            className="mt-1 block w-full rounded-md border-gray-300 focus:border-primary-main focus:ring focus:ring-primary-main focus:ring-opacity-50 text-sm"
                        >
                         <option value="">Select</option>
                           {Object.entries(LIKELIHOOD_VALUES).map(([key, value]) => (
                             <option key={key} value={value.value}>
                               {value.label}
                            </option>
                         ))}
                        </select>
                     </td>
                         <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                         <select
                           {...register(`assessments.${index}.impact`)}
                              className="mt-1 block w-full rounded-md border-gray-300 focus:border-primary-main focus:ring focus:ring-primary-main focus:ring-opacity-50 text-sm"
                           >
                              <option value="">Select</option>
                              {Object.entries(IMPACT_VALUES).map(([key, value]) => (
                                 <option key={key} value={value.value}>
                                   {value.label}
                                 </option>
                             ))}
                          </select>
                         </td>
                          </>
                           )}
                        <td className="px-4 py-4 whitespace-nowrap text-sm text-gray-700">
                      <RiskLevelDisplay
                          likelihood={assessment.likelihood}
                          impact={assessment.impact}
                          probability={assessment.probability}
                          severity={assessment.severity}
                        />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ))}

      <div className="flex justify-end">
        <button
          type="submit"
          disabled={isSubmitting}
          className={`px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition-colors duration-200 ${
            isSubmitting ? 'opacity-50 cursor-not-allowed' : ''
          }`}
        >
          {isSubmitting ? 'Saving...' : 'Next Step'}
        </button>
      </div>
    </form>
  );
}
